const raw = $json.output?.[0]?.content?.[0]?.text
  ?? $json.text
  ?? $json.message
  ?? '';

const cleaned = String(raw)
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

const data = JSON.parse(cleaned);

return [{
  json: {
    title: data.title,
    description: data.description,
    source_url: $('Set Video Details').first().json.source_url
  }
}];
